import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        List<TreeNode> firstPath = findPath(root, p);
        List<TreeNode> secondPath = findPath(root, q);
        TreeNode answer = null;
        for (int index = 0; index < Math.min(firstPath.size(), secondPath.size()); index++) {
            if (firstPath.get(index) != secondPath.get(index)) break;
            answer = firstPath.get(index);
        }
        return answer;
    }

    private List<TreeNode> findPath(TreeNode root, TreeNode target) {
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        parent.put(root, null);
        stack.push(root);
        while (!stack.isEmpty() && !parent.containsKey(target)) {
            TreeNode node = stack.pop();
            if (node.right != null) {
                parent.put(node.right, node);
                stack.push(node.right);
            }
            if (node.left != null) {
                parent.put(node.left, node);
                stack.push(node.left);
            }
        }
        List<TreeNode> path = new ArrayList<>();
        for (TreeNode node = target; node != null; node = parent.get(node)) path.add(node);
        Collections.reverse(path);
        return path;
    }
}

